<script setup>
import RouterLink from '../../components/PrototypeAwareRouterLink.vue'
import { computed, onMounted, ref } from 'vue'
import { useQuasar, copyToClipboard } from 'quasar'
import { useRouter } from 'vue-router'
import { useAuthStore } from '../../stores/auth.js'
import { collaboratorAccountsApi } from '../../services/collaborator-accounts.js'
import { errorMessage } from '../../services/http.js'
import { chooseConversationProfile } from './conversation-profile.js'
import { AREAS, CHANNELS, PERMISSION_GROUPS, canAction, canArea, isCollaborator, normalizedPermissions, permissionLevel } from '../../services/access.js'
const $q=useQuasar(), router=useRouter(), auth=useAuthStore()
const items=ref([]), form=ref(null), search=ref(''), permissionSearch=ref(''), loading=ref(false), busy=ref(false), error=ref(''), gmailConfigured=ref(false), metadata=ref([]), metadataError=ref('')
const levels=[{label:'Sem acesso',value:'none'},{label:'Somente visualizar',value:'view'},{label:'Visualizar e gerenciar',value:'manage'}]
const sensitive=new Set(['whatsapp_web.delete','assistant.configure','settings.credentials','web_settings.credentials','collaborators.permissions','collaborators.password','whatsapp_web.configure','whatsapp_cloud.configure','telegram.configure','email.configure'])
const visible=computed(()=>items.value.filter(item=>[item.name,item.username,item.nick,item.email].join(' ').toLowerCase().includes(search.value.toLowerCase())))
const loginUrl=computed(()=>new URL('/comunicacao/app/colaboradores',window.location.origin).href)
const mayCreate=computed(()=>canAction(auth.user,'collaborators','create'))
const mayEdit=computed(()=>canAction(auth.user,'collaborators','edit'))
const maySetPermissions=computed(()=>canAction(auth.user,'collaborators','permissions'))
const definitions=computed(()=>AREAS.map(area=>({...area,...(metadata.value.find(item=>item.key===area.key)||{}),group:area.group})))
const permissionGroups=computed(()=>PERMISSION_GROUPS.map(group=>({...group,areas:definitions.value.filter(area=>area.group===group.key&&[area.label,area.key,...(area.actions||[]).map(action=>action.label)].join(' ').toLowerCase().includes(permissionSearch.value.toLowerCase()))})).filter(group=>group.areas.length))
const allowedCount=computed(()=>form.value?definitions.value.filter(area=>form.value.permissions[area.key]!=='none').length:0)
const mayUseSignature=computed(()=>auth.user?.role==='admin')
function availableLevels(area){const max=area.maxLevel||'manage',own=isCollaborator(auth.user)?permissionLevel(auth.user,area.key):'manage';return levels.filter(level=>levels.findIndex(item=>item.value===level.value)<=Math.min(levels.findIndex(item=>item.value===max),levels.findIndex(item=>item.value===own)))}
function actionOptions(action){return[{label:(action.requiresExplicit||sensitive.has(action.key))?'Não autorizar por padrão':'Herdar de gerenciar',value:null},{label:'Permitir',value:true},{label:'Bloquear',value:false}]}
function setAction(key,value){if(value===null)delete form.value.permissions.actions[key];else form.value.permissions.actions[key]=value}
async function load(){loading.value=true;error.value='';metadataError.value='';try{const [data,catalog]=await Promise.all([collaboratorAccountsApi.list(),collaboratorAccountsApi.permissions()]);items.value=data.items||[];gmailConfigured.value=data.gmailConfigured===true;metadata.value=catalog.areas||catalog.items||catalog.definitions||[]}catch(e){error.value=errorMessage(e);metadataError.value='Não foi possível carregar a equipe e o catálogo de permissões.'}finally{loading.value=false}}
function edit(item={}){form.value={id:item._id||'',username:item.username||'',name:item.name||'',nick:item.nick||'',active:item.active!==false,signatureEnabled:item.signatureEnabled!==false,password:'',email:item.email||'',emailMfaEnabled:item.emailMfaEnabled===true,permissions:normalizedPermissions(item.permissions||{channels:[]})};permissionSearch.value='';error.value=''}
function preset(mode){if(!maySetPermissions.value)return;if(mode==='support'&&isCollaborator(auth.user)&&(!canArea(auth.user,'whatsapp_web',true)||!auth.user.permissions?.channels?.includes('whatsapp_web')))return;const value=normalizedPermissions({channels:[]});if(mode==='support'){value.mobile='view';value.whatsapp_web='manage';value.channels=['whatsapp_web'];value.contacts='view';value.help='view'}else if(mode==='reading'){for(const area of definitions.value)if(!isCollaborator(auth.user)||canArea(auth.user,area.key))value[area.key]='view';value.channels=isCollaborator(auth.user)?[...(auth.user.permissions?.channels||[])]:CHANNELS.map(item=>item.key)}form.value.permissions=value}
async function save(){busy.value=true;try{const payload={...form.value};if(!maySetPermissions.value)delete payload.permissions;if(form.value.id)await collaboratorAccountsApi.update(form.value.id,payload);else await collaboratorAccountsApi.create(payload);form.value=null;await load();$q.notify({type:'positive',message:'Perfil e permissões salvos.'})}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function copyLogin(){try{await copyToClipboard(loginUrl.value);$q.notify({type:'positive',message:'Link de login copiado.'})}catch{$q.notify({type:'info',message:loginUrl.value})}}
async function useProfile(item){busy.value=true;try{await chooseConversationProfile(item._id);await router.push('/app-mobile/web')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template>
<section class="collaborator-accounts">
  <header class="accounts-heading"><div><span class="eyebrow">EQUIPE DO SISTEMA</span><h1>Colaboradores</h1><p>Um login individual para as áreas, os canais e as ações que você autorizar.</p></div><div class="accounts-heading-actions"><q-btn outline no-caps color="primary" icon="link" label="Copiar link de login" @click="copyLogin"/><q-btn v-if="mayCreate" unelevated no-caps color="primary" icon="person_add" label="Novo colaborador" :disable="loading||!!metadataError" @click="edit()"/></div></header>
  <q-banner v-if="!gmailConfigured" rounded class="accounts-note q-mb-md">Para ativar a validação por e-mail da equipe, configure o Gmail em <RouterLink v-if="canArea(auth.user,'settings')" to="/">Início → Configurações</RouterLink><span v-else>Configurações, com um administrador autorizado</span>.</q-banner>
  <q-banner v-if="error&&!form" rounded class="bg-red-1 text-negative q-mb-md" role="alert">{{error}}<template #action><q-btn flat no-caps label="Tentar novamente" @click="load"/></template></q-banner>
  <div class="accounts-tools"><q-input v-model="search" outlined dense clearable label="Buscar nome, login ou assinatura" @clear="search=''"/><span>{{items.length}} perfil(is) · {{items.filter(item=>item.active).length}} ativo(s)</span></div><q-inner-loading :showing="loading"/>
  <div class="account-cards"><q-card v-for="item in visible" :key="item._id" flat bordered class="account-card"><q-card-section><div class="row items-center no-wrap q-gutter-sm"><q-avatar color="teal-1" text-color="teal-9">{{item.name?.slice(0,2).toUpperCase()}}</q-avatar><div class="col"><strong>{{item.name}}</strong><div class="text-caption text-grey-7">{{item.username}}</div></div><q-badge :color="item.active?'positive':'grey-6'">{{item.active?'Ativo':'Inativo'}}</q-badge></div><div class="account-signature"><small>Assinatura de conversa</small><strong>{{item.signatureEnabled ? item.nick+':' : 'Sem assinatura'}}</strong></div><div class="account-channels"><q-chip v-for="channel in CHANNELS.filter(channel=>item.permissions?.channels?.includes(channel.key))" :key="channel.key" dense color="teal-1" text-color="teal-9">{{channel.label}}</q-chip><span v-if="!item.permissions?.channels?.length">Sem canal liberado</span></div><p class="text-caption text-grey-7 q-mb-sm"><q-icon :name="item.emailMfaEnabled?'verified_user':'lock_outline'"/> {{item.emailMfaEnabled?'Senha + código por e-mail':'Autenticação por senha'}}</p><div class="account-stats"><span><b>{{item.stats?.total||0}}</b> Assumidos</span><span><b>{{(item.stats?.total||0)-(item.stats?.completed||0)}}</b> Em aberto</span><span><b>{{item.stats?.completed||0}}</b> Concluídos</span></div></q-card-section><q-card-actions align="between"><q-btn v-if="mayEdit" flat no-caps color="primary" icon="tune" label="Editar perfil" :disable="!!metadataError" @click="edit(item)"/><q-btn v-if="mayUseSignature&&item.active&&item.permissions?.channels?.includes('whatsapp_web')" flat no-caps color="primary" label="Usar assinatura" :loading="busy" @click="useProfile(item)"/></q-card-actions></q-card></div><p v-if="!loading&&!visible.length" class="accounts-empty">Nenhum perfil neste filtro.</p>
  <q-dialog :model-value="Boolean(form)" :persistent="busy" :maximized="$q.screen.lt.sm" @update:model-value="value=>{if(!value)form=null}"><q-card v-if="form" class="account-editor"><q-form @submit="save">
    <q-card-section class="editor-heading"><div><h2>{{form.id?'Editar colaborador':'Novo colaborador'}}</h2><p>Defina o acesso ao sistema inteiro. {{allowedCount}} área(s) liberada(s).</p></div><q-btn flat round icon="close" :disable="busy" aria-label="Fechar perfil do colaborador" @click="form=null"/></q-card-section><q-separator/>
    <q-card-section class="account-fields"><q-input v-model.trim="form.name" outlined label="Nome completo" maxlength="120" :rules="[value=>value.length>=2||'Informe o nome']"/><q-input v-model.trim="form.username" outlined label="Login individual" :readonly="!!form.id" :rules="[value=>/^[a-z0-9._-]{3,60}$/.test(value)||'Use 3 a 60 letras minúsculas, números, ponto ou traço']"/><q-input v-model="form.password" outlined type="password" :disable="!!form.id&&!canAction(auth.user,'collaborators','password')" autocomplete="new-password" :label="form.id?'Nova senha (opcional)':'Senha'" :rules="[value=>(form.id&&!value)||value.length>=12||'Mínimo de 12 caracteres']"/><q-input v-model.trim="form.email" outlined type="email" :disable="!!form.id&&!canAction(auth.user,'collaborators','password')" label="E-mail para autenticação multifator"/><q-input v-model="form.nick" outlined maxlength="60" label="Assinatura de conversa" hint="O negrito é aplicado automaticamente." :rules="[value=>Boolean(value.trim())||'Informe a assinatura']"/><div class="account-toggles"><q-toggle v-model="form.signatureEnabled" label="Assinar as respostas"/><q-toggle v-model="form.active" label="Perfil ativo"/></div></q-card-section>
    <q-card-section class="account-security"><q-toggle v-model="form.emailMfaEnabled" icon="verified_user" label="Exigir senha e código por e-mail" :disable="(!gmailConfigured&&!form.emailMfaEnabled)||(!!form.id&&!canAction(auth.user,'collaborators','password'))"/><p>O código de uso único será enviado ao e-mail deste colaborador. {{gmailConfigured?'Gmail configurado.':'Configure o Gmail antes de habilitar.'}}</p></q-card-section>
    <q-card-section class="permissions-section"><div class="permissions-title"><div><h3>Permissões do sistema</h3><p>Acesso por menu e por funcionalidade. Sem acesso é o padrão para novas áreas.</p></div><q-badge outline color="primary">{{allowedCount}} / {{definitions.length}}</q-badge></div><q-banner v-if="!maySetPermissions" rounded class="accounts-note">Seu perfil não pode alterar permissões. Ao salvar os dados pessoais, os acessos existentes serão mantidos.</q-banner>
      <div v-if="maySetPermissions" class="permission-presets"><q-btn flat dense no-caps icon="block" label="Limpar acessos" @click="preset('none')"/><q-btn flat dense no-caps icon="support_agent" label="Atendimento Web" :disable="isCollaborator(auth.user)&&(!canArea(auth.user,'whatsapp_web',true)||!auth.user.permissions?.channels?.includes('whatsapp_web'))" @click="preset('support')"/><q-btn flat dense no-caps icon="visibility" label="Somente leitura" @click="preset('reading')"/></div>
      <h3>Canais disponíveis</h3><div class="channel-permissions"><q-checkbox v-for="channel in CHANNELS" :key="channel.key" v-model="form.permissions.channels" :val="channel.key" :label="channel.label" :disable="!maySetPermissions||(isCollaborator(auth.user)&&!auth.user.permissions?.channels?.includes(channel.key))"/></div><p class="permission-tip">O canal e o menu precisam estar liberados. Cada conexão mantém seu próprio número e credenciais.</p>
      <q-input v-model="permissionSearch" outlined dense clearable label="Buscar menu ou funcionalidade" class="permission-search" @clear="permissionSearch=''"/>
      <q-expansion-item v-for="group in permissionGroups" :key="group.key" default-opened :label="group.label" class="permission-group"><div v-for="area in group.areas" :key="area.key" class="permission-area"><div class="permission-area-level"><span><q-icon :name="area.icon"/><strong>{{area.label}}</strong></span><q-select v-model="form.permissions[area.key]" outlined dense :options="availableLevels(area)" emit-value map-options :disable="!maySetPermissions" :aria-label="'Permissão de '+area.label"/></div><div v-if="area.key==='assistant'" class="permission-special-note"><q-icon name="smart_toy"/><span>Visualizar libera a conversa e as consultas. Gerenciar permite revisar ações dentro das outras permissões deste perfil. Configurar a chave exige autorização explícita e o consumo usa a conta OpenAI configurada.</span></div><div v-if="area.maxLevel==='view'" class="permission-tip">As alterações desta área são reservadas ao administrador.</div><q-expansion-item v-if="area.actions?.length" dense :label="`Funcionalidades (${area.actions.length})`" class="permission-actions"><div v-for="action in area.actions" :key="action.key" class="permission-action"><div><span>{{action.label}}</span><small v-if="(action.requiresExplicit||sensitive.has(action.key))">Exige autorização explícita</small></div><q-select :model-value="form.permissions.actions[action.key]??null" :options="actionOptions(action)" outlined dense emit-value map-options :disable="!maySetPermissions||form.permissions[area.key]!=='manage'" :aria-label="area.label+' · '+action.label" @update:model-value="value=>setAction(action.key,value)"/></div><p class="permission-tip">Funcionalidades exigem “Visualizar e gerenciar”. Bloquear uma ação restringe esse acesso; permitir não libera outras áreas.</p></q-expansion-item></div></q-expansion-item>
      <p v-if="!permissionGroups.length" class="permission-tip">Nenhum menu encontrado para esta busca.</p><p v-if="form.id" class="permission-tip">Salvar alterações encerra as sessões existentes deste perfil.</p><q-banner v-if="error" rounded class="bg-red-1 text-negative" role="alert">{{error}}</q-banner>
    </q-card-section><q-card-actions align="right" class="editor-actions"><q-btn flat no-caps label="Cancelar" :disable="busy" @click="form=null"/><q-btn unelevated no-caps color="primary" type="submit" label="Salvar perfil e permissões" :loading="busy" :disable="!!metadataError"/></q-card-actions>
  </q-form></q-card></q-dialog>
</section>
</template>
<style scoped>
.collaborator-accounts{position:relative;min-width:0}.accounts-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}.accounts-heading h1{font-size:30px;line-height:1.2;margin:8px 0}.accounts-heading p{font-size:13px;color:var(--muted);margin:0}.accounts-heading .eyebrow{font-size:10px;color:var(--brand-dark);letter-spacing:.12em}.accounts-heading-actions{display:flex;gap:8px;flex-wrap:wrap}.accounts-tools{display:flex;align-items:center;gap:16px;justify-content:space-between;margin-bottom:18px}.accounts-tools .q-field{max-width:400px;flex:1}.accounts-tools>span{font-size:12px;color:var(--muted)}.accounts-note{background:color-mix(in srgb,var(--brand) 8%,white);color:var(--ink);border:1px solid var(--line);font-size:12px;line-height:1.7}.accounts-note a{color:var(--brand-dark)}.account-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(285px,1fr));gap:16px}.account-card{border-color:var(--line);border-radius:18px}.account-signature{margin:18px 0 12px;padding:12px;background:color-mix(in srgb,var(--brand) 8%,white);border-radius:12px}.account-signature small,.account-signature strong{display:block}.account-signature small{font-size:10px;color:var(--muted)}.account-signature strong{font-size:14px;margin-top:4px}.account-channels{display:flex;flex-wrap:wrap;gap:2px;min-height:32px}.account-channels>span{font-size:11px;color:var(--muted)}.account-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding-top:14px;border-top:1px solid var(--line)}.account-stats span{font-size:10px;color:var(--muted)}.account-stats b{display:block;font-size:22px;color:var(--ink)}.accounts-empty{padding:40px;text-align:center;color:var(--muted)}.account-editor{width:900px;max-width:96vw;max-height:92dvh;border-radius:20px;color:var(--ink);background:linear-gradient(140deg,color-mix(in srgb,var(--brand) 4%,white),white);overflow:auto}.editor-heading{display:flex;justify-content:space-between;align-items:start;position:sticky;top:0;background:white;z-index:3}.editor-heading h2{font-size:23px;line-height:1.25;margin:0}.editor-heading p{font-size:12px;color:var(--muted);margin:8px 0 0}.account-fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.account-toggles{display:flex;flex-direction:column}.account-security{margin:0 16px;padding:12px;background:color-mix(in srgb,var(--brand) 8%,white);border-radius:14px}.account-security p{font-size:11px;color:var(--muted);margin:3px 12px}.account-editor h3{font-size:16px;line-height:1.4;margin:12px 0}.channel-permissions{display:flex;gap:8px;flex-wrap:wrap}.permissions-title{display:flex;align-items:center;justify-content:space-between;gap:12px}.permissions-title p,.permission-tip{font-size:11px;color:var(--muted);line-height:1.7;margin:8px 0 12px}.permission-presets{display:flex;flex-wrap:wrap;gap:4px;margin:14px 0}.permission-presets .q-btn{font-size:11px}.permission-search{margin:18px 0}.permission-group{border:1px solid var(--line);border-radius:13px;overflow:hidden;margin-top:12px;background:white}.permission-group :deep(.q-expansion-item__container>.q-item){font-weight:700;font-size:13px;background:color-mix(in srgb,var(--brand) 5%,white)}.permission-area{padding:15px;border-top:1px solid var(--line)}.permission-area-level{display:grid;grid-template-columns:minmax(0,1fr) 235px;align-items:center;gap:12px}.permission-area-level>span{display:flex;align-items:center;gap:9px;font-size:13px;min-width:0}.permission-area-level .q-icon{font-size:22px;color:var(--brand-dark);flex:none}.permission-area-level strong{overflow-wrap:anywhere}.permission-actions{margin-top:12px;border-radius:9px;border:1px solid var(--line);overflow:hidden}.permission-actions :deep(.q-item){font-weight:500!important;background:transparent!important;font-size:11px!important}.permission-action{display:grid;grid-template-columns:minmax(0,1fr) 215px;gap:12px;align-items:center;padding:10px 12px;border-top:1px solid var(--line);font-size:12px}.permission-action small{display:block;font-size:10px;color:var(--brand-dark);margin-top:4px}.permission-actions>.q-expansion-item__container>div>.permission-tip{padding:0 12px}.permission-special-note{display:flex;gap:8px;padding:11px;border-radius:9px;background:color-mix(in srgb,var(--brand) 8%,white);font-size:11px;line-height:1.7;margin-top:12px}.permission-special-note .q-icon{font-size:22px;color:var(--brand-dark)}.editor-actions{position:sticky;bottom:0;background:white;border-top:1px solid var(--line);z-index:3;padding:14px 16px}@media(max-width:650px){.accounts-heading,.accounts-tools{align-items:stretch;flex-direction:column}.accounts-tools .q-field{max-width:none}.accounts-heading-actions>.q-btn{flex:1}.account-fields{grid-template-columns:1fr}.permission-area-level,.permission-action{grid-template-columns:minmax(0,1fr);gap:9px}.account-editor{max-width:100vw;width:100vw;max-height:100dvh;border-radius:0}.account-cards{grid-template-columns:1fr}.account-editor h2{font-size:21px}.permission-area{padding:12px}.permissions-section{padding:16px 12px}}
</style>
